-- SQL analysis for the customer segmentation project (SQLite dialect).
-- All data is SYNTHETIC (generated by src/data_generator.py).
-- Tables: customers(customer_id, signup_date, country, age, acquisition_channel,
--                   newsletter_subscriber)
--         orders(order_id, customer_id, order_date, order_value, items_count,
--                payment_method, discount_used)
-- Dates are stored as text in YYYY-MM-DD format.
-- Run with: python src/run_sql.py
-- Note: keep semicolons only at the end of statements, because run_sql.py splits on them.

-- Q1: How many rows, distinct customers and what date range does each table cover?
SELECT 'customers' AS table_name,
       COUNT(*) AS n_rows,
       COUNT(DISTINCT customer_id) AS n_customers,
       MIN(signup_date) AS first_date,
       MAX(signup_date) AS last_date
FROM customers
UNION ALL
SELECT 'orders',
       COUNT(*),
       COUNT(DISTINCT customer_id),
       MIN(order_date),
       MAX(order_date)
FROM orders;

-- Q2: What does the RFM table look like for the 10 highest-spending customers?
-- Snapshot date = one day after the last order, as in src/utils.py.
SELECT customer_id,
       CAST(julianday((SELECT MAX(order_date) FROM orders)) + 1
            - julianday(MAX(order_date)) AS INTEGER) AS recency,
       COUNT(*) AS frequency,
       ROUND(SUM(order_value), 2) AS monetary
FROM orders
GROUP BY customer_id
ORDER BY monetary DESC
LIMIT 10;

-- Q3: How are customers scored 1-5 on R, F and M and assigned a rule-based segment?
-- NTILE(5) mirrors the quintile scoring in Python, with ties broken by customer_id.
WITH rfm AS (
    SELECT customer_id,
           CAST(julianday((SELECT MAX(order_date) FROM orders)) + 1
                - julianday(MAX(order_date)) AS INTEGER) AS recency,
           COUNT(*) AS frequency,
           SUM(order_value) AS monetary
    FROM orders
    GROUP BY customer_id
),
scored AS (
    SELECT customer_id, recency, frequency, ROUND(monetary, 2) AS monetary,
           NTILE(5) OVER (ORDER BY recency DESC, customer_id) AS r_score,
           NTILE(5) OVER (ORDER BY frequency ASC, customer_id) AS f_score,
           NTILE(5) OVER (ORDER BY monetary ASC, customer_id) AS m_score
    FROM rfm
)
SELECT customer_id, recency, frequency, monetary, r_score, f_score, m_score,
       CASE
           WHEN r_score >= 4 AND f_score >= 4 THEN 'Champions'
           WHEN r_score >= 3 AND f_score >= 3 THEN 'Loyal'
           WHEN r_score <= 2 AND f_score >= 3 THEN 'At Risk'
           WHEN r_score <= 2 AND f_score <= 2 THEN 'Lapsed'
           WHEN r_score >= 4 AND f_score <= 2 THEN 'New / Promising'
           ELSE 'Occasional'
       END AS rfm_segment
FROM scored
ORDER BY r_score + f_score + m_score DESC, customer_id
LIMIT 10;

-- Q4: How large is each rule-based segment and what share of revenue does it bring?
WITH rfm AS (
    SELECT customer_id,
           CAST(julianday((SELECT MAX(order_date) FROM orders)) + 1
                - julianday(MAX(order_date)) AS INTEGER) AS recency,
           COUNT(*) AS frequency,
           SUM(order_value) AS monetary
    FROM orders
    GROUP BY customer_id
),
scored AS (
    SELECT customer_id, recency, frequency, monetary,
           NTILE(5) OVER (ORDER BY recency DESC, customer_id) AS r_score,
           NTILE(5) OVER (ORDER BY frequency ASC, customer_id) AS f_score
    FROM rfm
),
segmented AS (
    SELECT *,
           CASE
               WHEN r_score >= 4 AND f_score >= 4 THEN 'Champions'
               WHEN r_score >= 3 AND f_score >= 3 THEN 'Loyal'
               WHEN r_score <= 2 AND f_score >= 3 THEN 'At Risk'
               WHEN r_score <= 2 AND f_score <= 2 THEN 'Lapsed'
               WHEN r_score >= 4 AND f_score <= 2 THEN 'New / Promising'
               ELSE 'Occasional'
           END AS rfm_segment
    FROM scored
)
SELECT rfm_segment,
       COUNT(*) AS customers,
       ROUND(COUNT(*) * 1.0 / SUM(COUNT(*)) OVER (), 3) AS customer_share,
       ROUND(AVG(recency), 1) AS avg_recency,
       ROUND(AVG(frequency), 2) AS avg_frequency,
       ROUND(AVG(monetary), 2) AS avg_monetary,
       ROUND(SUM(monetary) * 1.0 / SUM(SUM(monetary)) OVER (), 3) AS revenue_share
FROM segmented
GROUP BY rfm_segment
ORDER BY avg_monetary DESC;

-- Q5: How concentrated is revenue? Compare customer spend quintiles (1 = lowest spenders).
WITH spend AS (
    SELECT customer_id, SUM(order_value) AS monetary
    FROM orders
    GROUP BY customer_id
),
bucketed AS (
    SELECT customer_id, monetary,
           NTILE(5) OVER (ORDER BY monetary ASC, customer_id) AS spend_quintile
    FROM spend
)
SELECT spend_quintile,
       COUNT(*) AS customers,
       ROUND(AVG(monetary), 2) AS avg_spend,
       ROUND(SUM(monetary), 2) AS revenue,
       ROUND(SUM(monetary) * 1.0 / SUM(SUM(monetary)) OVER (), 3) AS revenue_share
FROM bucketed
GROUP BY spend_quintile
ORDER BY spend_quintile DESC;

-- Q6: Which acquisition channels bring the most valuable customers?
SELECT c.acquisition_channel,
       COUNT(DISTINCT c.customer_id) AS customers,
       COUNT(o.order_id) AS orders,
       ROUND(COUNT(o.order_id) * 1.0 / COUNT(DISTINCT c.customer_id), 2) AS orders_per_customer,
       ROUND(SUM(o.order_value) / COUNT(DISTINCT c.customer_id), 2) AS revenue_per_customer,
       ROUND(AVG(o.order_value), 2) AS avg_order_value
FROM customers AS c
JOIN orders AS o ON o.customer_id = c.customer_id
GROUP BY c.acquisition_channel
ORDER BY revenue_per_customer DESC;

-- Q7: How do monthly revenue and active customers develop, with a running revenue total?
SELECT strftime('%Y-%m', order_date) AS month,
       COUNT(*) AS orders,
       COUNT(DISTINCT customer_id) AS active_customers,
       ROUND(SUM(order_value), 2) AS revenue,
       ROUND(SUM(SUM(order_value)) OVER (ORDER BY strftime('%Y-%m', order_date)), 2)
           AS cumulative_revenue
FROM orders
GROUP BY month
ORDER BY month DESC;
